    BigInteger[] dpB = new BigInteger[m + 2];
    // 初始化dpB[i]
    for (int i = 0; i < m + 2; i++) dpB[i] = new BigInteger("0");

    for (int i = m - 1; i >= 7; i--) {
      // B叫数字i的方案数 = A叫数字i+1的方案数 + A叫数字i+2的方案数
